    {"name":"write","arguments":{"path":"two_bucket.py","overwrite":True,"content":"from collections import deque\nfrom math import gcd\n\ndef measure(bucket_one, bucket_two, goal, start_bucket):\n    if start_bucket not in (\"one\", \"two\"):\n        raise ValueError(\"start_bucket must be 'one' or 'two'\")\n    if bucket_one <= 0 or bucket_two <= 0 or goal < 0:\n        raise ValueError(\"bucket sizes must be positive and goal non-negative\")\n    if goal > max(bucket_one, bucket_two) or (goal and goal % gcd(bucket_one, bucket_two)):\n        raise ValueError(\"goal cannot be measured with these bucket sizes\")\n    caps = (bucket_one, bucket_two)\n    start = (bucket_one, 0) if start_bucket == \"one\" else (0, bucket_two)\n    queue = deque([(start, 1)])\n    seen = {start}\n    while queue:\n        (a, b), moves = queue.popleft()\n        if (start_bucket == \"one\" and a == goal) or (start_bucket == \"two\" and b == goal):\n            return {\"moves\": moves, \"goal_bucket\": start_bucket, \"other_bucket\": b if start_bucket == \"one\" else a}\n        amount = min(a, caps[1] - b)\n        poured_ab = (a - amount, b + amount)\n        amount = min(b, caps[0] - a)\n        poured_ba = (a + amount, b - amount)\n        next_states = [(0, b), (a, 0), (caps[0], b), (a, caps[1]), poured_ab, poured_ba]\n        for state in next_states:\n            if state == (0, caps[1]) if start_bucket == \"one\" else state == (caps[0], 0):\n                continue\n            if state != (a, b) and state not in seen:\n                seen.add(state)\n                queue.append((state, moves + 1))\n    raise ValueError(\"goal cannot be reached without violating the starting-bucket rule\")\n"}},
